(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.2)*20 + Math.cos(y*0.012-t*0.15)*15 + Math.sin((x+y)*0.008+t*0.1)*10;
  const w1y = Math.cos(y*0.018-t*0.18)*18 + Math.sin(x*0.014+t*0.22)*12 + Math.cos((x-y)*0.009-t*0.12)*8;
  const w2x = Math.sin(w1x*0.02+t*0.3)*8 + Math.cos(w1y*0.015-t*0.25)*6;
  const w2y = Math.cos(w1y*0.022+t*0.28)*7 + Math.sin(w1x*0.018-t*0.32)*5;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+2)*50, 0.11, 2.1],
    [400+Math.cos(t*0.55+1)*60, 200+Math.sin(t*0.75+4)*70, 0.05, 2.8]
  ];
  let aS = 0, iS = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
  }
  const act = aS/8, inh = iS/8;
  const bg1 = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2 = (Math.sin(sx*0.08-sy*0.06+t*1.6) + Math.cos(sx*0.07+sy*0.09-t*1.3))/2;
  const bg3 = (Math.sin(sx*0.15+sy*0.12+t*2.5) + Math.sin(sx*0.13-sy*0.16-t*2.2))/2;
  const bg = bg1 + bg2*0.4 + bg3*0.15;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.35
    + Math.sin(dist*0.08-ang*2+t*0.8)*0.2 + Math.sin(dist*0.03+ang*6-t*2.0)*0.15;
  const rings = Math.sin(dist*0.1 - t*3)*Math.exp(-dist*0.005)*0.3;
  const secAct = Math.sin(sx*0.1+t*0.7)*Math.cos(sy*0.08-t*0.5);
  const secInh = Math.sin((sx+sy)*0.07-t*0.9)*0.7;
  const secReaction = Math.tanh((secAct - secInh)*1.5)*0.2;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.2;
  const raw = act - inh*0.7 + bg*0.25 + spiral + rings + secReaction;
  const reaction = Math.tanh(raw*2.2);
  const dx = Math.abs(Math.sin((sx+1)*0.15)*Math.sin(sy*0.15) - Math.sin((sx-1)*0.15)*Math.sin(sy*0.15));
  const dy = Math.abs(Math.sin(sx*0.15)*Math.sin((sy+1)*0.15) - Math.sin(sx*0.15)*Math.sin((sy-1)*0.15));
  const edge = Math.min(1, (dx+dy)*15);
  const blend = reaction*0.65 + cell*0.2 + secReaction*0.15, v = blend*0.5+0.5;
  const pal = [[10,12,55],[18,50,120],[20,110,140],[45,165,155],[210,185,60],[220,140,55],[195,80,75],[130,40,90],[10,12,55]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.75 + Math.sin(reaction*Math.PI)*0.25;
  const glow = Math.abs(reaction) > 0.65 ? 1.2 : 1.0;
  const edgeBright = 1.0 + edge*0.4*glow;
  const vig = 1.0 - Math.sqrt((x-cx)**2+(y-cy)**2)/400*0.25;
  const fl = lum * edgeBright * vig;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*fl)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*fl)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*fl)|0
  ];
}
